    /**
     * Диалог очень прост но имеет начальное состояние
     * и к нему надо привязать коллбэки
     * **/
    dialogSettingsBody({isMusicOn, isSoundOn, onSoundSwitch, onMusicSwitch, onCloseClick}: {
        isMusicOn: boolean,
        isSoundOn: boolean,
        onSoundSwitch: (isSoundOn: boolean) => void,
        onMusicSwitch: (isMusicOn: boolean) => void,
        onCloseClick: () => void,
    }): Phaser.GameObjects.Container {

        const builder = this;
        const {scene} = this;

        const container = scene.add.container(0, 0, []);
        const bg = builder.dialogBgLightNine({width: 857, height: 577});
        const titleText = getLocalizedText('settings.title');
        const title = builder.dialogTitle({label: titleText});
        const closeButton = builder.buttonCloseDialog(onCloseClick);

        const soundButton = builder.buttonSwitchSound(onSoundSwitch);
        soundButton.switch(isSoundOn);

        const musicButton = builder.buttonSwitchMusic(onMusicSwitch);
        musicButton.switch(isMusicOn);

        const align = new Align();
        align.anchor(bg).centerX(title).topIn(title, 40);
        align.rightIn(closeButton, -20).topIn(closeButton, 20)

        const buttonGroup = layoutChain({
            children: [soundButton, musicButton],
            alignToAnchor: AlignMethod.CENTER_X,
            alignToNext: AlignMethod.BOTTOM_TO,
            nextOffsetY: 20
        });

        align.anchor(bg).centerX(buttonGroup).topIn(buttonGroup, 167);

        container.add([
            bg, title, closeButton, soundButton, musicButton
        ])
        return container;
    }

