import { Align } from "@kvisaz/phaser-sugar";
import { ViewElementBuilder } from "../../assets";
import { SceneEvents } from "../../common";
import { ExternalTopbarDialog } from "../../common/game-core";
import { ILogicShopItem, isInAppPurchaseId, isRewardPurchaseId, PurchaseId } from "../../logic";
import { GameServiceProvider } from "../../services";
import { SpiderGameScenes } from "../scenes";
import { IModalSceneData } from "../shared/modal-scenes/types";
import { getAvailableGameShopItems } from "../shared/shopScene/getAvailableGameShopItems";
import { IShopSceneParentEvents } from "./events";

interface IMessageDialogProps {
  text: string;
  buttonText: string;
  onClose?: () => void;
}

export class ShopScene extends Phaser.Scene {
  private parentSceneKey = "";
  private dialog?: ExternalTopbarDialog;
  private messageDialog?: ExternalTopbarDialog;
  private parentSceneEvents?: SceneEvents<IShopSceneParentEvents>;

  constructor() {
    super(SpiderGameScenes.Shop);
  }

  preload() {}

  create(data: IModalSceneData) {
    this.parentSceneKey = data.parentSceneKey;
    this.cameras.main.setBackgroundColor("rgba(0,0,0,0)");
    this.parentSceneEvents = new SceneEvents<IShopSceneParentEvents>({
      scene: this.scene.get(this.parentSceneKey),
    });

    const shopItems = getAvailableGameShopItems();
    if (shopItems.length === 0) {
      this.closeScene();
      return;
    }

    const builder = new ViewElementBuilder(this);
    this.dialog = builder.dialogShop({
      shopItems,
      onItemBuyClick: (item) => {
        void this.onItemBuyClick(item);
      },
      onClose: () => this.closeScene(),
    });

    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.parentSceneEvents?.unSubscribeAll();
      this.parentSceneEvents = undefined;
      this.dialog = undefined;
      this.messageDialog = undefined;
    });

    this.dialog.show();
  }

  private closeScene(): void {
    this.scene.resume(this.parentSceneKey);
    this.scene.stop();
  }

  private async onItemBuyClick(item: ILogicShopItem): Promise<void> {
    if (!isInAppPurchaseId(item.id) && !isRewardPurchaseId(item.id)) {
      console.warn("unknown game purchase id", item.id);
      return;
    }

    const result = await GameServiceProvider.get().shopPurchase(item.id);
    if ("error" in result) {
      console.warn("game shop purchase failed", result.error);
      this.showErrorDialog();
      return;
    }

    this.emitPurchaseApplied(item.id);
    this.showSuccessDialog();
  }

  private emitPurchaseApplied(purchaseId: PurchaseId): void {
    this.parentSceneEvents?.emit("gameShopPurchaseApplied", {
      purchaseId,
    });
  }

  private showSuccessDialog(): void {
    this.destroyDialogs();
    this.showMessageDialog({
      text: "Спасибо за покупку",
      buttonText: "Ok",
      onClose: () => this.closeScene(),
    });
  }

  private showErrorDialog(): void {
    this.destroyDialogs();
    this.showMessageDialog({
      text: "Ой, ошибка. Повторите попозже",
      buttonText: "Ok",
      onClose: () => this.closeScene(),
    });
  }

  private showMessageDialog(props: IMessageDialogProps): void {
    const builder = new ViewElementBuilder(this);
    const align = new Align();

    const dialogText = builder.textDialog(props.text, {
      align: "center",
      fixedWidth: 700,
      wordWrap: {
        width: 700,
      },
    });

    const button = builder.buttonPrimary(props.buttonText, () => {
      this.messageDialog?.close();
    }, {
      width: 300,
      height: 92,
      fontSizePx: 40,
    });

    align.anchor(dialogText).centerX(button).bottomTo(button, 42);

    const content = this.add.container(0, 0, [dialogText, button]);
    this.messageDialog = builder.dialogExternalTopTitle({
      title: "",
      content,
      width: 900,
      height: 380,
      isCloseOnOverlayClick: true,
      onClose: () => {
        this.messageDialog = undefined;
        props.onClose?.();
      },
    });

    this.messageDialog.show();
  }

  private destroyDialogs(): void {
    this.dialog?.destroy();
    this.dialog = undefined;
    this.messageDialog?.destroy();
    this.messageDialog = undefined;
  }
}
