import { SoundPlayerFeature } from "../shared";
import { BgAssetManager } from "../shared/background";
import { SettingsSoundSync } from "../shared/settingsScene/SettingsSoundSync";
import { SpiderGameScenes } from "../scenes";
import { SpiderGameAdsSceneLauncher } from "./ads";
import { SpiderGameSceneView } from "./SpiderGameSceneView";
import { SpiderGameSceneModalHandler } from "./SpiderGameSceneModalHandler";

export class SpiderGameScene extends Phaser.Scene {
  constructor() {
    super(SpiderGameScenes.SpiderGame);
  }

  preload() {}

  create() {
    const scene = this;
    new BgAssetManager({ scene, isColorOverlay: true });
    new SoundPlayerFeature({ scene });
    new SettingsSoundSync({ scene });
    new SpiderGameAdsSceneLauncher({ scene });
    new SpiderGameSceneModalHandler({ scene });
    new SpiderGameSceneView({ scene });
  }
}
