import {SceneEvents} from "../../common";
import {IModalSceneData} from "../shared/modal-scenes/types";
import {SpiderGameScenes} from "../scenes";
import {ISpiderStartSceneEvents} from "./events";
import {showSettings} from '../shared/dialog/settings';
import {applySettingsAudio} from "../shared/settingsScene/applySettingsAudio";

interface ISpiderStartSceneModalHandlerProps {
    scene: Phaser.Scene;
}

export class SpiderStartSceneModalHandler {
    private readonly sceneEvents: SceneEvents<ISpiderStartSceneEvents>;

    constructor(private readonly props: ISpiderStartSceneModalHandlerProps) {
        this.sceneEvents = new SceneEvents<ISpiderStartSceneEvents>({scene: props.scene});
        // this.sceneEvents.on("onSettingsButtonClick", () => this.launchModalScene(SpiderGameScenes.Settings));
        this.sceneEvents.on("onShopButtonClick", () => this.launchModalScene(SpiderGameScenes.Shop));

        this.sceneEvents.on("onSettingsButtonClick", () => {
            showSettings({parentScene: this.props.scene})
        });

        this.sceneEvents.on("gameSettingsUpdated", (settings) => {
            applySettingsAudio({
                scene: this.props.scene,
                isInputUnlocked: true,
                isMusicOn: settings.isMusicOn,
                isSoundOn: settings.isSoundOn,
            });
        });
    }

    private launchModalScene(sceneKey: SpiderGameScenes.Settings | SpiderGameScenes.Shop): void {
        const {scene} = this.props;
        if (scene.scene.isActive(sceneKey)) {
            return;
        }

        const data: IModalSceneData = {
            parentSceneKey: scene.scene.key,
        };
        scene.scene.launch(sceneKey, data);
        scene.scene.bringToTop(sceneKey);
        scene.scene.pause();
    }
}
