import { State, StateConnector } from "../../common";
import { ISettingsState } from "../../logic";
import { GameServiceProvider } from "../../services";
import { SpiderGameScenes } from "../scenes";
import { SettingsDialog } from "../shared/settings/SettingsDialog";
import { IModalSceneData } from "../shared/modal-scenes/types";
import { applySettingsAudio } from "../shared/settingsScene/applySettingsAudio";

export class SettingsScene extends Phaser.Scene {
  private parentSceneKey = "";

  constructor() {
    super(SpiderGameScenes.Settings);
  }

  preload() {}

  create(data: IModalSceneData) {
    this.parentSceneKey = data.parentSceneKey;
    this.cameras.main.setBackgroundColor("rgba(0,0,0,0)");

    const gameService = GameServiceProvider.get();
    const initialSettings = gameService.getPlayerData().settings;
    const settingsState = new State<ISettingsState>({
      ...initialSettings,
    });
    const settingsConnector = new StateConnector(settingsState);

    settingsConnector.on((settings) => {
      gameService.setPlayerData({ settings });
      applySettingsAudio({
        scene: this,
        isInputUnlocked: true,
        isMusicOn: settings.isMusicOn,
        isSoundOn: settings.isSoundOn,
      });
    });

    applySettingsAudio({
      scene: this,
      isInputUnlocked: true,
      isMusicOn: initialSettings.isMusicOn,
      isSoundOn: initialSettings.isSoundOn,
    });

    const dialog = new SettingsDialog({
      scene: this,
      settings: settingsConnector,
      onCloseClick: () => this.closeScene(settingsConnector),
    }).create();

    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      settingsConnector.unSubScribeAll();
    });

    dialog.show();
  }

  private closeScene(settingsConnector: StateConnector<ISettingsState>): void {
    settingsConnector.unSubScribeAll();
    this.scene.resume(this.parentSceneKey);
    this.scene.stop();
  }
}
