import {GameServiceProvider} from '../../../../services';
import {ISettingsState} from '../../../../logic';
import {openCommonModalInScene} from '../../../../common/game-core';
import {CommonModal} from '../../../../common/game-core/components/CommonModal';
import {ViewElementBuilder} from '../../../../assets';

interface IProps {
    parentScene: Phaser.Scene;
}

export const showSettings = ({parentScene}: IProps) => {

    const gameService = GameServiceProvider.get();
    const createContent = makeDialogBody.bind(null, gameService, parentScene);

    /** запускаем диалог в новой сцене **/
    openCommonModalInScene({
        parentScene,
        createContent,
        props: {
            animationDuration: 180,
            isCloseOnOverlayClick: true,
            onClose: () => {
                console.log('settings closed')
            },
        },
    });
}

function makeDialogBody(
    gameService: ReturnType<typeof GameServiceProvider.get>,
    parentScene: Phaser.Scene,
    scene: Phaser.Scene,
) {
    const builder = new ViewElementBuilder(scene);
    const initialSettings = gameService.getPlayerData().settings;
    return builder.dialogSettingsBody({
        isMusicOn: initialSettings.isMusicOn,
        isSoundOn: initialSettings.isSoundOn,
        onMusicSwitch: (isMusicOn) => {
            const nextSettings: ISettingsState = {
                ...gameService.getPlayerData().settings,
                isMusicOn,
            };
            gameService.setPlayerData({settings: nextSettings});
            parentScene.events.emit("gameSettingsUpdated", nextSettings);
        },
        onSoundSwitch: (isSoundOn) => {
            const nextSettings: ISettingsState = {
                ...gameService.getPlayerData().settings,
                isSoundOn,
            };
            gameService.setPlayerData({settings: nextSettings});
            parentScene.events.emit("gameSettingsUpdated", nextSettings);
        },
        onCloseClick: () => scene.events.emit(CommonModal.EVENT_CLOSE_COMMAND),
    });
}
