import { defaultSpiderConfig, ISpiderConfig, ISpiderExposedState, SceneEvents, State } from "../../../common";
import { ISpiderGameSceneViewLogicEvents } from "./events";
import { SpiderDealSession } from "./SpiderDealSession";

interface IProps {
  /**
   * важный момент - стараемся минимизировать использование сцены
   * допускаются
   * - работа с событиями
   * - работа с таймерами
   * запрещено обращение к свойствам сцены ради обращения к игровым объектам
   * **/
  scene: Phaser.Scene;
  spiderConfig?: ISpiderConfig;
}

const defaultState: ISpiderExposedState = {
  step: "idle",
  historyLength: 0,
  dealsLeft: 0,
  isDealPossible: false,
  isUndoPossible: false,
  completedSequences: 0,
  isCollectPossible: false,
  isHintPossible: false,
  isMagicPossible: false,
  stockCount: 0,
  tableauCounts: [],
  isWin: false,
};

export class SpiderGameSceneViewLogic {
  private readonly state: State<ISpiderExposedState>;
  private readonly sceneEvents: SceneEvents<ISpiderGameSceneViewLogicEvents>;
  private readonly unSubs: Array<() => void> = [];

  private readonly spiderConfig: ISpiderConfig;
  private readonly dealSession: SpiderDealSession;

  constructor(private readonly props: IProps) {
    this.spiderConfig = props.spiderConfig ?? defaultSpiderConfig;
    this.dealSession = new SpiderDealSession({ spiderConfig: this.spiderConfig });

    this.state = new State<ISpiderExposedState>({ ...defaultState });
    this.unSubs.push(() => this.state.unSubScribeAll());

    this.sceneEvents = new SceneEvents<ISpiderGameSceneViewLogicEvents>({ scene: props.scene });
    this.unSubs.push(() => this.sceneEvents.unSubscribeAll());

    this.subscribeToUiEvents();
    this.subscribeToSpiderEvents();
  }

  destroy() {
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
  }

  observable() {
    return this.state;
  }

  startNewGame({ shuffleDeck }: { shuffleDeck: boolean }) {
    this.state.setState({ ...defaultState });
    const cards = shuffleDeck ? this.dealSession.nextDeal() : this.dealSession.replayDeal();
    this.sceneEvents.emit("spiderStart", { cards, config: this.spiderConfig });
  }

  private subscribeToUiEvents() {
    const { sceneEvents } = this;

    sceneEvents.on("uiNewGameClick", () => {
      this.startNewGame({ shuffleDeck: true });
    });

    sceneEvents.on("uiReplayClick", () => {
      this.startNewGame({ shuffleDeck: false });
    });
  }

  private subscribeToSpiderEvents() {
    const { sceneEvents } = this;

    sceneEvents.on("spiderStateUpdate", (state) => {
      this.state.setState(state);
    });
  }
}
