import { onSceneShutdown } from "../../../common/scenes";
import { GameServiceProvider } from "../../../services";
import { applySettingsAudio } from "./applySettingsAudio";

interface ISettingsSoundSyncProps {
  scene: Phaser.Scene;
}

/** Задача - применить настройки к звуку **/
export class SettingsSoundSync {
  private isInputUnlocked = false;
  private readonly onFirstPointer = () => {
    this.isInputUnlocked = true;
    this.sync();
  };

  constructor(private readonly props: ISettingsSoundSyncProps) {
    props.scene.input.once(Phaser.Input.Events.POINTER_DOWN, this.onFirstPointer);
    onSceneShutdown(props.scene, () => this.destroy());
    this.sync();
  }

  destroy(): void {
    this.props.scene.input.off(Phaser.Input.Events.POINTER_DOWN, this.onFirstPointer);
  }

  sync(): void {
    const settings = GameServiceProvider.get().getPlayerData().settings;
    applySettingsAudio({
      scene: this.props.scene,
      isInputUnlocked: this.isInputUnlocked,
      isMusicOn: settings.isMusicOn,
      isSoundOn: settings.isSoundOn,
    });
  }
}
