import { SceneEvents } from "../../common";
import { IConfirmDialogRequest, IConfirmResult } from "../shared/confirm/types";
import { ConfirmDialog } from "../shared/ConfirmDialog";
import { IModalSceneData } from "../shared/modal-scenes/types";
import { SpiderGameScenes } from "../scenes";
import { ISpiderGameSceneEvents } from "./events";

interface ISpiderGameSceneModalHandlerProps {
  scene: Phaser.Scene;
}

const backConfirmRequest: IConfirmDialogRequest = {
  titleKey: "backDialog.Title",
  infoKey: "backDialog.Info",
  theme: "danger",
};

export class SpiderGameSceneModalHandler {
  private readonly sceneEvents: SceneEvents<ISpiderGameSceneEvents>;
  private readonly confirmDialog: ConfirmDialog;

  constructor(private readonly props: ISpiderGameSceneModalHandlerProps) {
    this.sceneEvents = new SceneEvents<ISpiderGameSceneEvents>({ scene: props.scene });
    this.confirmDialog = new ConfirmDialog({ scene: props.scene });

    props.scene.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.confirmDialog.destroy();
    });

    this.sceneEvents.on("onSettingsButtonClick", () => this.launchModalScene(SpiderGameScenes.Settings));
    this.sceneEvents.on("onShopButtonClick", () => this.launchModalScene(SpiderGameScenes.Shop));
    this.sceneEvents.on("onBackButtonClick", () => this.showBackConfirm());
  }

  private launchModalScene(sceneKey: SpiderGameScenes.Settings | SpiderGameScenes.Shop): void {
    const { scene } = this.props;
    if (scene.scene.isActive(sceneKey)) {
      return;
    }

    const data: IModalSceneData = {
      parentSceneKey: scene.scene.key,
    };
    scene.scene.launch(sceneKey, data);
    scene.scene.bringToTop(sceneKey);
    scene.scene.pause();
  }

  private showBackConfirm(): void {
    this.confirmDialog.confirm(backConfirmRequest, (result) => this.onBackConfirm(result));
  }

  private onBackConfirm(result: IConfirmResult): void {
    if (!result.confirmed) {
      return;
    }

    this.props.scene.scene.start(SpiderGameScenes.SpiderStart);
  }
}
